SELECT avg(latency_ms) AS avg_latency_per_call
FROM marts.fct_requests
WHERE setup = 'B_local' AND split = 'test';

SELECT count(*) as n_decisions
FROM marts.fct_outcomes
WHERE split = 'test' AND arm = 'primary' AND setup = 'B_local';

SELECT tenant_id, monthly_budget_usd 
FROM marts.dim_tenant 
WHERE display_name = 'billing';

SELECT priority, first_response_minutes, resolution_hours 
FROM support.sla_policies 
WHERE tenant_id = 'sales' AND priority = 'high';

SELECT count(*) as n_decisions
FROM marts.fct_outcomes
WHERE setup = 'A_tfidf' AND split = 'tune';

SELECT count(DISTINCT gold_label) as distinct_gold_intents
FROM marts.fct_outcomes
WHERE split = 'test';

SELECT count(*) 
FROM support.tickets 
WHERE tenant_id = 'billing' AND channel = 'chat';

SELECT count(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT count(*) 
FROM support.agents 
WHERE hourly_cost_usd > 6 AND is_active AND team NOT LIKE 'test-%';

SELECT COUNT(*) 
FROM support.agents 
WHERE is_active = TRUE AND team NOT LIKE 'test-%';

select sum(total_cost_usd) as total_spent_usd 
from marts.fct_outcomes 
where setup = 'B_local' and split = 'test' and arm = 'primary';

select sum(total_cost_usd) / nullif(sum(n_correct), 0) as cost_per_correct_usd
from marts.mart_cost_per_outcome
where setup = 'B_local' and split = 'test' and arm = 'primary';

SELECT count(*) filter (where ai_predicted_intent is distinct from final_intent)::numeric / count(*) 
FROM support.tickets 
WHERE tenant_id not like 'test-%';
